using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DisorientedEffect", menuName = "Data/Battle/Effects/Enemy/Disoriented Effect")]
public class DisorientedEffect : Effect
{
	[Header("Ranged Value")]
	[SerializeField]
	private RangedInt rangedValue;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		if (amount > 10000)
		{
			return string.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("DisorientedInf_D"), rangedValue.minValue, rangedValue.maxValue);
		}
		return base.GetEffectDescription(amount, effectOwner);
	}

	protected override string GetLocalizedDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(EffectID + "_D");
	}

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return GetEffectDescriptionWithAmountReplacedWithX(localizedDescription, rangedValue.minValue, rangedValue.maxValue, GetNumberToReplaceWithX());
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), rangedValue.minValue, rangedValue.maxValue, amount);
	}

	public Dice RandomizeValue(Dice dice)
	{
		for (int i = 0; i < dice.GetDiceFaces().Length; i++)
		{
			BattleAction battleAction = dice.GetDiceFaces()[i].BattleAction;
			if (battleAction is PurifyAction || battleAction is CorruptAction)
			{
				dice.GetDiceFaces()[i].ActionValue = rangedValue.Random();
				if (battleAction is PurifyAction && ReferenceSingleton<MiscOmensHandler>.Instance.EntropyHoodOmenAction != null)
				{
					dice.GetDiceFaces()[i].ActionValue = ReferenceSingleton<MiscOmensHandler>.Instance.EntropyHoodOmenAction(dice.GetDiceFaces()[i].ActionValue);
				}
			}
			dice.GetDiceFaces()[i].BattleAction = battleAction;
			if (!dice.GetDiceFaces()[i].EnableSecondAction)
			{
				continue;
			}
			BattleAction secondBattleAction = dice.GetDiceFaces()[i].SecondBattleAction;
			if (secondBattleAction is PurifyAction || secondBattleAction is CorruptAction)
			{
				dice.GetDiceFaces()[i].SecondActionValue = rangedValue.Random();
				if (secondBattleAction is PurifyAction && ReferenceSingleton<MiscOmensHandler>.Instance.EntropyHoodOmenAction != null)
				{
					dice.GetDiceFaces()[i].SecondActionValue = ReferenceSingleton<MiscOmensHandler>.Instance.EntropyHoodOmenAction(dice.GetDiceFaces()[i].SecondActionValue);
				}
			}
			dice.GetDiceFaces()[i].SecondBattleAction = secondBattleAction;
		}
		return dice;
	}
}
